	@Test
	void emptyLeftForwardsEntryAndNestedConstantBindingsForSelect() throws Exception {
		SimpleValueFactory valueFactory = SimpleValueFactory.getInstance();
		IRI predicate = valueFactory.createIRI("urn:p");
		IRI secondPredicate = valueFactory.createIRI("urn:q");
		IRI object = valueFactory.createIRI("urn:o");
		TupleExpr serviceExpression = new Join(
				new StatementPattern(Var.of("s"), Var.of("p", predicate), Var.of("mid")),
				new StatementPattern(Var.of("mid"), Var.of("q", secondPredicate), Var.of("o", object)));
		Service service = service(serviceExpression,
				"{ ?s <urn:p> ?mid . ?mid <urn:q> <urn:o> }");

		MapBindingSet entryBindings = new MapBindingSet();
		IRI subject = valueFactory.createIRI("urn:s");
		entryBindings.addBinding("s", subject);

		FederatedService federatedService = mock(FederatedService.class);
		when(federatedService.select(eq(service), anySet(), any(BindingSet.class), eq(service.getBaseURI())))
				.thenReturn(new EmptyIteration<>());
		EvaluationStrategy strategy = strategyFor(federatedService);

		try (ServiceJoinIterator iterator = new ServiceJoinIterator(
				new EmptyIteration<>(), service, entryBindings, strategy)) {
			assertThat(iterator.hasNext()).isFalse();
		}

		ArgumentCaptor<Set> projectionCaptor = ArgumentCaptor.forClass(Set.class);
		ArgumentCaptor<BindingSet> bindingsCaptor = ArgumentCaptor.forClass(BindingSet.class);
		verify(federatedService).select(eq(service), projectionCaptor.capture(), bindingsCaptor.capture(),
				eq(service.getBaseURI()));
		assertThat(projectionCaptor.getValue()).containsExactly("mid");
		assertThat(bindingsCaptor.getValue().getBindingNames())
				.containsExactlyInAnyOrder("serviceRef", "s", "p", "q", "o");
		assertThat(bindingsCaptor.getValue().getValue("serviceRef"))
				.isEqualTo(service.getServiceRef().getValue());
		assertThat(bindingsCaptor.getValue().getValue("s")).isEqualTo(subject);
		assertThat(bindingsCaptor.getValue().getValue("p")).isEqualTo(predicate);
		assertThat(bindingsCaptor.getValue().getValue("q")).isEqualTo(secondPredicate);
		assertThat(bindingsCaptor.getValue().getValue("o")).isEqualTo(object);
		verify(federatedService, never()).ask(any(), any(BindingSet.class), any());
	}

